import { readFile, writeFile } from 'node:fs/promises';
import { relative, sep } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parseModule, validateImportBindings } from './module-parser.mjs';

const root = new URL('../', import.meta.url);
const rootPath = fileURLToPath(root);
const entryFile = 'app.js';
const outputUrl = new URL('bundle.js', root);

const modules = new Map();
const visiting = new Set();

async function visit(file) {
  if (modules.has(file)) return;
  if (visiting.has(file)) throw new Error('Circular module dependency at ' + file);
  visiting.add(file);

  const sourceUrl = new URL(file, root);
  if (!sourceUrl.href.startsWith(root.href)) throw new Error('Module escapes project root: ' + file);
  const source = await readFile(sourceUrl, 'utf8');
  const parsed = parseModule(source, file);
  for (const { specifier, names } of parsed.imports) {
    if (!specifier.startsWith('.')) throw new Error('External imports are not supported: ' + specifier);
    const dependencyUrl = new URL(specifier, sourceUrl);
    if (!dependencyUrl.href.startsWith(root.href)) throw new Error('Module escapes project root: ' + specifier);
    const dependency = relative(rootPath, fileURLToPath(dependencyUrl)).split(sep).join('/');
    await visit(dependency);
    validateImportBindings(file, names, dependency, modules.get(dependency).exports);
  }
  visiting.delete(file);
  modules.set(file, { code: parsed.code.trim(), exports: parsed.exports });
}

await visit(entryFile);
const sections = [...modules].map(([file, module]) => '// Source: ' + file + '\n' + module.code);
const bundle = [
  '// Generated by scripts/build-bundle.mjs. Do not edit directly.',
  '(function () {',
  "  'use strict';",
  sections.join('\n\n'),
  '})();',
  ''
].join('\n');

if (process.argv.includes('--check')) {
  const current = await readFile(outputUrl, 'utf8').catch(() => '');
  if (current !== bundle) {
    console.error('bundle.js is out of date. Run npm run build.');
    process.exitCode = 1;
  }
} else {
  await writeFile(outputUrl, bundle);
  console.log('Generated bundle.js from ' + modules.size + ' source modules.');
}
